import java.util.HashMap;
import java.util.Optional;

public class Nachschlagewerk {

    public static void main(String[] args) {
        HashMap<String, String> buch = new HashMap<>();
        buch.put("Hund", "dog");

        Optional<String> ergebnis = Optional.ofNullable(buch.get("Katze"));
        System.out.println(ergebnis.orElse("Unbekannt"));

        Optional.ofNullable(buch.get("Hund"))
                .ifPresent(w -> System.out.println("Hund = " + w));
    }
}

